def listCities(authToken, q=None, normalizedKey=None, countryCode=None, provinceZh=None, status=None, page=None, pageSize=None, orderBy=None, order=None, **_extra):
    import json, os, datetime, time, hashlib, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0467000" if __import__("os").path.isdir("./environment_mix/0467000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _log(status_s, error=None, meta=None, cred=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "req_" + hashlib.sha256((now_iso + "|" + str(random.random())).encode("utf-8")).hexdigest()[:16],
            "endpoint": "listCities",
            "auth_credential": cred,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "message": (error or {}).get("message") if isinstance(error, dict) else None,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        }
        logs.append(entry)
        _save("request_logs.json", logs)

    # Validate auth token against a store if exists; otherwise accept any non-empty token.
    if not isinstance(authToken, str) or authToken.strip() == "":
        e = _err("UNAUTHORIZED", "Missing or invalid authToken.")
        _log("error", e["error"])
        return e

    creds = _load("auth_tokens.json")
    cred_id = None
    if isinstance(creds, list) and creds:
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("token") == authToken or c.get("id") == authToken:
                if c.get("status") in (None, "active"):
                    cred_id = c.get("id") or c.get("token")
                    break
        if cred_id is None:
            e = _err("UNAUTHORIZED", "Invalid authToken.")
            _log("error", e["error"])
            return e
    else:
        cred_id = authToken

    # Rate limiting/quota if configured
    cfg = _load("service_config.json")
    if isinstance(cfg, dict):
        rl = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rl, int) and rl > 0:
            window_start = (now - datetime.timedelta(seconds=60)).isoformat() + "Z"
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != "listCities":
                    continue
                if r.get("auth_credential") != cred_id:
                    continue
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= window_start:
                    cnt += 1
            if cnt >= rl:
                e = _err("RATE_LIMIT", "Too many requests; rate limit exceeded.", limit=rl, window_seconds=60)
                _log("error", e["error"], cred=cred_id)
                return e
        if isinstance(quota, int) and quota >= 0:
            day_prefix = now.date().isoformat()
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != "listCities":
                    continue
                if r.get("auth_credential") != cred_id:
                    continue
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts.startswith(day_prefix):
                    cnt += 1
            if cnt >= quota:
                e = _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=quota, period="day")
                _log("error", e["error"], cred=cred_id)
                return e

    # Validate params
    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 20
    if orderBy is None:
        orderBy = "updated_at"
    if order is None:
        order = "desc"

    if not isinstance(page, int) or page < 1:
        e = _err("VALIDATION_ERROR", "page must be an integer >= 1.")
        _log("error", e["error"], cred=cred_id)
        return e
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 100:
        e = _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 100.")
        _log("error", e["error"], cred=cred_id)
        return e
    if orderBy not in ("created_at", "updated_at", "name_zh"):
        e = _err("VALIDATION_ERROR", "orderBy must be one of created_at, updated_at, name_zh.")
        _log("error", e["error"], cred=cred_id)
        return e
    if order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be asc or desc.")
        _log("error", e["error"], cred=cred_id)
        return e
    if status is not None and status not in ("active", "disabled"):
        e = _err("VALIDATION_ERROR", "status must be active or disabled.")
        _log("error", e["error"], cred=cred_id)
        return e
    if countryCode is not None and not isinstance(countryCode, str):
        e = _err("VALIDATION_ERROR", "countryCode must be a string.")
        _log("error", e["error"], cred=cred_id)
        return e

    cities = _load("cities.json")
    if not isinstance(cities, list):
        cities = []

    def _contains(hay, needle):
        if hay is None:
            return False
        return needle.lower() in str(hay).lower()

    rows = []
    for c in cities:
        if not isinstance(c, dict):
            continue
        if q is not None:
            if not isinstance(q, str):
                e = _err("VALIDATION_ERROR", "q must be a string.")
                _log("error", e["error"], cred=cred_id)
                return e
            qq = q.strip()
            if qq != "":
                if not (_contains(c.get("name_zh"), qq) or _contains(c.get("name_en"), qq)):
                    continue
        if normalizedKey is not None:
            if not isinstance(normalizedKey, str):
                e = _err("VALIDATION_ERROR", "normalizedKey must be a string.")
                _log("error", e["error"], cred=cred_id)
                return e
            if c.get("normalized_key") != normalizedKey:
                continue
        if countryCode is not None:
            if c.get("country_code") != countryCode:
                continue
        if provinceZh is not None:
            if not isinstance(provinceZh, str):
                e = _err("VALIDATION_ERROR", "provinceZh must be a string.")
                _log("error", e["error"], cred=cred_id)
                return e
            if c.get("province_zh") != provinceZh:
                continue
        if status is not None:
            if c.get("status") != status:
                continue
        rows.append(c)

    reverse = (order == "desc")
    def _key(x):
        v = x.get(orderBy)
        return (v is None, v)
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    start_i = (page - 1) * pageSize
    end_i = start_i + pageSize
    page_rows = rows[start_i:end_i]
    has_more = end_i < total

    resp = {
        "data": page_rows,
        "pagination": {
            "page": page,
            "pageSize": pageSize,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None
        }
    }
    _log("ok", meta={"returned": len(page_rows), "total": total}, cred=cred_id)
    return resp

def updateCity(authToken, id, nameZh=None, nameEn=None, provinceZh=None, countryCode=None, normalizedKey=None, status=None, **_extra):
    import json, os, datetime, time, hashlib, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0467000" if __import__("os").path.isdir("./environment_mix/0467000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _log(status_s, error=None, meta=None, cred=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "req_" + hashlib.sha256((now_iso + "|" + str(random.random())).encode("utf-8")).hexdigest()[:16],
            "endpoint": "updateCity",
            "auth_credential": cred,
            "status": status_s,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "message": (error or {}).get("message") if isinstance(error, dict) else None,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now_iso,
            "meta": meta or {}
        }
        logs.append(entry)
        _save("request_logs.json", logs)

    # Auth token
    if not isinstance(authToken, str) or authToken.strip() == "":
        e = _err("UNAUTHORIZED", "Missing or invalid authToken.")
        _log("error", e["error"])
        return e

    creds = _load("auth_tokens.json")
    cred_id = None
    if isinstance(creds, list) and creds:
        for c in creds:
            if not isinstance(c, dict):
                continue
            if c.get("token") == authToken or c.get("id") == authToken:
                if c.get("status") in (None, "active"):
                    cred_id = c.get("id") or c.get("token")
                    break
        if cred_id is None:
            e = _err("UNAUTHORIZED", "Invalid authToken.")
            _log("error", e["error"])
            return e
    else:
        cred_id = authToken

    if not isinstance(id, str) or id.strip() == "":
        e = _err("VALIDATION_ERROR", "id must be a non-empty string.")
        _log("error", e["error"], cred=cred_id)
        return e
    if status is not None and status not in ("active", "disabled"):
        e = _err("VALIDATION_ERROR", "status must be active or disabled.")
        _log("error", e["error"], cred=cred_id)
        return e
    if countryCode is not None and countryCode != "CN":
        e = _err("VALIDATION_ERROR", "countryCode must be 'CN'.")
        _log("error", e["error"], cred=cred_id)
        return e

    cities = _load("cities.json")
    if not isinstance(cities, list):
        cities = []

    city = None
    for c in cities:
        if isinstance(c, dict) and c.get("id") == id:
            city = c
            break
    if city is None:
        e = _err("NOT_FOUND", "City not found.")
        _log("error", e["error"], cred=cred_id)
        return e

    # Prepare updates; enforce constraints
    if nameZh is not None:
        if not isinstance(nameZh, str) or nameZh.strip() == "":
            e = _err("VALIDATION_ERROR", "nameZh must be a non-empty string.")
            _log("error", e["error"], cred=cred_id)
            return e
    if normalizedKey is not None:
        if not isinstance(normalizedKey, str) or normalizedKey.strip() == "":
            e = _err("VALIDATION_ERROR", "normalizedKey must be a non-empty string.")
            _log("error", e["error"], cred=cred_id)
            return e
    if nameEn is not None and not (isinstance(nameEn, str) or nameEn is None):
        e = _err("VALIDATION_ERROR", "nameEn must be a string or null.")
        _log("error", e["error"], cred=cred_id)
        return e
    if provinceZh is not None and not (isinstance(provinceZh, str) or provinceZh is None):
        e = _err("VALIDATION_ERROR", "provinceZh must be a string or null.")
        _log("error", e["error"], cred=cred_id)
        return e

    # Lifecycle transition check
    if status is not None and status != city.get("status"):
        transitions = {"active": ["disabled"], "disabled": ["active"]}
        cur = city.get("status")
        if cur not in transitions or status not in transitions[cur]:
            e = _err("INVALID_TRANSITION", f"Cannot transition city status from {cur} to {status}.")
            _log("error", e["error"], cred=cred_id)
            return e

    # Unique(country_code, normalized_key)
    new_country = countryCode if countryCode is not None else city.get("country_code")
    new_norm = normalizedKey if normalizedKey is not None else city.get("normalized_key")
    if new_country is None or new_norm is None or str(new_norm).strip() == "":
        e = _err("VALIDATION_ERROR", "countryCode/normalizedKey cannot be empty.")
        _log("error", e["error"], cred=cred_id)
        return e
    for c in cities:
        if not isinstance(c, dict):
            continue
        if c.get("id") == id:
            continue
        if c.get("country_code") == new_country and c.get("normalized_key") == new_norm:
            e = _err("CONFLICT", "Another city with the same (country_code, normalized_key) already exists.")
            _log("error", e["error"], cred=cred_id)
            return e

    # Apply updates
    changed = False
    if nameZh is not None and nameZh != city.get("name_zh"):
        city["name_zh"] = nameZh
        changed = True
    if nameEn is not None and nameEn != city.get("name_en"):
        city["name_en"] = nameEn
        changed = True
    if provinceZh is not None and provinceZh != city.get("province_zh"):
        city["province_zh"] = provinceZh
        changed = True
    if countryCode is not None and countryCode != city.get("country_code"):
        city["country_code"] = countryCode
        changed = True
    if normalizedKey is not None and normalizedKey != city.get("normalized_key"):
        city["normalized_key"] = normalizedKey
        changed = True
    if status is not None and status != city.get("status"):
        city["status"] = status
        changed = True

    if not changed:
        # Idempotent update: still return the existing city
        resp = {"data": city}
        _log("ok", meta={"id": id, "changed": False}, cred=cred_id)
        return resp

    city["updated_at"] = now_iso
    _save("cities.json", cities)

    resp = {"data": city}
    _log("ok", meta={"id": id, "changed": True}, cred=cred_id)
    return resp

