                if r.get("endpoint") != "listStations":
                    continue
                if r.get("auth_credential") != cred_id:
                    continue
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= window_start:
                    cnt += 1
            if cnt >= rl:
                e = _err("RATE_LIMIT", "Too many requests; rate limit exceeded.", limit=rl, window_seconds=60)
                _log("error", e["error"], cred=cred_id)
                return e
        if isinstance(quota, int) and quota >= 0:
            day_prefix = now.date().isoformat()
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != "listStations":
                    continue
                if r.get("auth_credential") != cred_id:
                    continue
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts.startswith(day_prefix):
                    cnt += 1
            if cnt >= quota:
                e = _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=quota, period="day")
                _log("error", e["error"], cred=cred_id)
                return e

    # Defaults & validation
    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 20
    if orderBy is None:
