                continue
            for f in token_fields:
                v = c.get(f)
                if isinstance(v, str) and v == t:
                    candidates.append(c)
                    break

        def _is_active_status(s):
            return s in (None, "active", "enabled")

        for c in candidates:
            acc = None
            ws = None
            acc_id = c.get("account_id") or c.get("accountId")
            ws_id = c.get("workspace_id") or c.get("workspaceId")
            if acc_id:
                acc = acc_by_id.get(acc_id)
                if not acc or not _is_active_status(acc.get("status")):
                    continue
            if ws_id:
                ws = ws_by_id.get(ws_id)
                if not ws or not _is_active_status(ws.get("status")):
                    continue
            # If credential doesn't reference account/workspace, still accept if active.
            if not _is_active_status(c.get("status")):
                continue
            return {"credential": c, "account": acc, "workspace": ws}
        return None

