        _log(400, cred_id, "VALIDATION_ERROR", "nameZh must be a non-empty string when provided.")
        return _err("VALIDATION_ERROR", "nameZh must be a non-empty string when provided.")
    if stationCode is not None and (not isinstance(stationCode, str) or stationCode == ""):
        _log(400, cred_id, "VALIDATION_ERROR", "stationCode must be a non-empty string when provided.")
        return _err("VALIDATION_ERROR", "stationCode must be a non-empty string when provided.")
    if telecode is not None and (not isinstance(telecode, str)):
        _log(400, cred_id, "VALIDATION_ERROR", "telecode must be a string when provided.")
        return _err("VALIDATION_ERROR", "telecode must be a string when provided.")
    if isPrimaryForCity is not None and not isinstance(isPrimaryForCity, bool):
        _log(400, cred_id, "VALIDATION_ERROR", "isPrimaryForCity must be a boolean when provided.")
        return _err("VALIDATION_ERROR", "isPrimaryForCity must be a boolean when provided.")
