    if not isinstance(stations, list):
        stations = []
    cities = _load("cities.json")
    if not isinstance(cities, list):
        cities = []

    stn = None
    for r in stations:
        if isinstance(r, dict) and r.get("id") == id:
            stn = r
            break
    if not stn:
        _log(404, cred_id, "NOT_FOUND", "Station not found.")
        return _err("NOT_FOUND", "Station not found.", id=id)

    # Validate referenced city exists if changing cityId
    if cityId is not None:
        city_exists = any(isinstance(c, dict) and c.get("id") == cityId for c in cities)
        if not city_exists:
            _log(404, cred_id, "NOT_FOUND", "Referenced cityId not found.")
            return _err("NOT_FOUND", "Referenced cityId not found.", cityId=cityId)

    # Lifecycle transition validation
    if status is not None:
        cur = stn.get("status")
        if cur not in ("active", "disabled"):
            _log(409, cred_id, "INVALID_TRANSITION", "Station has unknown current status; cannot transition.")
            return _err("INVALID_TRANSITION", "Station has unknown current status; cannot transition.", current_status=cur)
        if status != cur:
            allowed = {"active": ["disabled"], "disabled": ["active"]}.get(cur, [])
            if status not in allowed:
                _log(409, cred_id, "INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}.")
                return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}.", current_status=cur, requested_status=status)

    # Apply changes (only provided fields)
    new_city_id = cityId if cityId is not None else stn.get("city_id")
    new_name_zh = nameZh if nameZh is not None else stn.get("name_zh")
    new_station_code = stationCode if stationCode is not None else stn.get("station_code")
    new_telecode = telecode if telecode is not None else stn.get("telecode")
    new_is_primary = isPrimaryForCity if isPrimaryForCity is not None else stn.get("is_primary_for_city")
    new_lat = latitude if latitude is not None else stn.get("latitude")
    new_lng = longitude if longitude is not None else stn.get("longitude")
    new_status = status if status is not None else stn.get("status")

    # Constraint checks
    if not isinstance(new_name_zh, str) or new_name_zh == "":
        _log(400, cred_id, "VALIDATION_ERROR", "name_zh cannot be empty.")
        return _err("VALIDATION_ERROR", "name_zh cannot be empty.")
    if not isinstance(new_station_code, str) or new_station_code == "":
        _log(400, cred_id, "VALIDATION_ERROR", "station_code cannot be empty.")
        return _err("VALIDATION_ERROR", "station_code cannot be empty.")
    if new_lat is not None and (new_lat < -90 or new_lat > 90):
        _log(400, cred_id, "VALIDATION_ERROR", "latitude must be between -90 and 90.")
        return _err("VALIDATION_ERROR", "latitude must be between -90 and 90.")
    if new_lng is not None and (new_lng < -180 or new_lng > 180):
        _log(400, cred_id, "VALIDATION_ERROR", "longitude must be between -180 and 180.")
        return _err("VALIDATION_ERROR", "longitude must be between -180 and 180.")

    # Uniqueness: station_code unique
    for r in stations:
        if not isinstance(r, dict) or r.get("id") == id:
            continue
        if r.get("station_code") == new_station_code:
            _log(409, cred_id, "CONFLICT", "stationCode already exists.")
            return _err("CONFLICT", "stationCode already exists.", stationCode=new_station_code)

    # Uniqueness: (city_id, name_zh) unique
    for r in stations:
        if not isinstance(r, dict) or r.get("id") == id:
            continue
        if r.get("city_id") == new_city_id and r.get("name_zh") == new_name_zh:
            _log(409, cred_id, "CONFLICT", "A station with the same name already exists in the target city.")
            return _err("CONFLICT", "A station with the same name already exists in the target city.", cityId=new_city_id, nameZh=new_name_zh)

    # If setting primary, ensure other stations in that city are not primary
    # (best-effort business rule; schema doesn't declare unique but typical domain)
    if new_is_primary is True:
        for r in stations:
            if not isinstance(r, dict) or r.get("id") == id:
                continue
            if r.get("city_id") == new_city_id and r.get("is_primary_for_city") is True:
                r["is_primary_for_city"] = False
                r["updated_at"] = now_iso

    # Persist
    changed = False
    def _set(k, v):
        nonlocal changed
        if stn.get(k) != v:
            stn[k] = v
            changed = True

    _set("city_id", new_city_id)
    _set("name_zh", new_name_zh)
    _set("station_code", new_station_code)
    _set("telecode", new_telecode)
    _set("is_primary_for_city", new_is_primary)
    _set("latitude", new_lat)
    _set("longitude", new_lng)
    _set("status", new_status)

    if changed:
        stn["updated_at"] = now_iso
        _save("stations.json", stations)

    _log(200, cred_id)
    return {"station": stn, "changed": changed}

